pax_font_t const terminal_font_raw = {
    .name         = "Unifont 8x16",
    .n_ranges     = sizeof(terminal_ranges) / sizeof(terminal_ranges[0]),
    .ranges       = terminal_ranges,
    .default_size = 16,
    .recommend_aa = false,
};

bool terminal_font_has_glyph(uint32_t codepoint) {
    for (size_t i = 0; i < sizeof(terminal_ranges) / sizeof(terminal_ranges[0]); i++) {
        if (codepoint >= terminal_ranges[i].start && codepoint <= terminal_ranges[i].end) {
            return true;
        }
    }
    return false;
}
